     "pagina": 54,
     "texto": "A tendência de aumento da frequência e da intensidade desses fenômenos impõe ao Estado a necessidade de incorporar a adaptação climática como uma política permanente e transversal, capaz de reduzir vulnerabilidades e ampliar a resiliência da sociedade gaúcha.",
