     "natureza": "diagnostico",
     "pagina": 13,
     "texto": "EFESA CIVIL E RESILIÊNCIA CLIMÁTICA Os eventos extremos registrados nos últimos anos evidenciaram que o Rio Grande do Sul precisa substituir uma cultura de resposta emergencial por uma política permanente de prevenção e gestão de riscos.",
