     "texto": "São esses grupos que enfrentam primeiro e com maior intensidade os efeitos da degradação ambiental, da expansão predatória dos grandes empreendimentos e da insuficiência de políticas públicas de proteção, prevenção e adaptação às mudanças climáticas.",
     "inicio": 239,
